#include "preprocessor.hpp"
std::string position_text(const Position &position) {
    return position.file + ":" + std::to_string(position.line);
}
bool builtin(const std::string &name) { return word_in("__LINE__ __FILE__ __COUNTER__", name); }
std::string Macro::signature() const {
    if (!function)
        return name;
    std::string result = name + "(";
    for (size_t i = 0; i < parameters.size(); ++i) {
        if (i)
            result += ", ";
        result += variadic && i + 1 == parameters.size() ? "..." : parameters[i];
    }
    return result + ")";
}
void check_name(const Tokens &tokens, const std::string &directive) {
    if (tokens.empty())
        throw PreprocessingError{"no macro name given in #" + directive + " directive"};
    if (tokens[0].kind != "identifier")
        throw PreprocessingError{"macro names must be identifiers"};
    const std::string &name = tokens[0].spelling;
    if (name == "defined")
        throw PreprocessingError{"\"defined\" cannot be used as a macro name"};
    if (builtin(name))
        throw PreprocessingError{std::string(directive == "define"
                                                 ? "cannot redefine builtin macro \""
                                                 : "cannot undefine builtin macro \"") +
                                 name + "\""};
}
std::shared_ptr<Macro> parse_definition(Tokens tokens, Position position, bool main_file) {
    check_name(tokens, "define");
    auto result = std::make_shared<Macro>();
    result->name = tokens[0].spelling;
    result->position = position;
    result->main_file = main_file;
    const std::string variadic_name = "__VA_ARGS__",
                      variadic_error =
                          "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro";
    if (result->name == variadic_name)
        throw PreprocessingError{variadic_error};
    size_t index = 1;
    if (index < tokens.size() && tokens[index].spelling == "(" && !tokens[index].space) {
        result->function = true;
        ++index;
        if (index == tokens.size())
            throw PreprocessingError{"missing ')' in macro parameter list"};
        if (tokens[index].spelling == ")")
            ++index;
        else {
            std::set<std::string> seen;
            while (true) {
                if (index == tokens.size())
                    throw PreprocessingError{"missing ')' in macro parameter list"};
                Token token = tokens[index++];
                std::string parameter = token.spelling;
                if (parameter == "...") {
                    result->variadic = true;
                    parameter = variadic_name;
                } else if (token.kind == "identifier") {
                    if (parameter == variadic_name)
                        throw PreprocessingError{variadic_error};
                    if (seen.count(parameter))
                        throw PreprocessingError{"duplicate macro parameter \"" + parameter + "\""};
                } else
                    throw PreprocessingError{"expected parameter name, found \"" + parameter +
                                             "\""};
                seen.insert(parameter);
                result->parameters.push_back(parameter);
                if (index == tokens.size())
                    throw PreprocessingError{"missing ')' in macro parameter list"};
                std::string next = tokens[index++].spelling;
                if (next == ")")
                    break;
                if (result->variadic)
                    throw PreprocessingError{"expected ')' after \"...\", found \"" + next + "\""};
                if (next != ",")
                    throw PreprocessingError{"expected ',' or ')', found \"" + next + "\""};
            }
        }
    }
    result->replacement.assign(tokens.begin() + index, tokens.end());
    if (!result->replacement.empty()) {
        result->replacement[0].space = false;
        if (result->replacement.front().spelling == "##" ||
            result->replacement.back().spelling == "##")
            throw PreprocessingError{"'##' cannot appear at either end of a macro expansion"};
    }
    std::set<std::string> parameters(result->parameters.begin(), result->parameters.end());
    for (size_t i = 0; i < result->replacement.size(); ++i) {
        const Token &token = result->replacement[i];
        if (token.kind == "identifier" && token.spelling == variadic_name && !result->variadic)
            throw PreprocessingError{variadic_error};
        if (token.spelling == "#" && result->function &&
            (i + 1 == result->replacement.size() ||
             result->replacement[i + 1].kind != "identifier" ||
             !parameters.count(result->replacement[i + 1].spelling)))
            throw PreprocessingError{"'#' is not followed by a macro parameter"};
    }
    return result;
}
bool Macro::identical(const Macro &other) const {
    if (function != other.function || variadic != other.variadic ||
        parameters != other.parameters || replacement.size() != other.replacement.size())
        return false;
    for (size_t i = 0; i < replacement.size(); ++i)
        if (replacement[i].spelling != other.replacement[i].spelling ||
            replacement[i].space != other.replacement[i].space)
            return false;
    return true;
}

#include "preprocessor.hpp"
static std::set<std::string> intersection(const std::set<std::string> &left,
                                          const std::set<std::string> &right) {
    std::set<std::string> result;
    std::set_intersection(left.begin(), left.end(), right.begin(), right.end(),
                          std::inserter(result, result.end()));
    return result;
}
static Token stringize(const Tokens &raw, const Token &hash) {
    Token result;
    result.kind = "string";
    result.space = hash.space;
    result.spelling = "\"";
    for (size_t i = 0; i < raw.size(); ++i) {
        if (i && raw[i].space)
            result.spelling += " ";
        for (char c : raw[i].spelling) {
            if ((raw[i].kind == "string" || raw[i].kind == "character") && (c == '\\' || c == '"'))
                result.spelling += '\\';
            result.spelling += c;
        }
    }
    result.spelling += '"';
    return result;
}
static Tokens paste(Preprocessor &processor, const Inclusion &inclusion, Token left, Token right,
                    const Token &invocation) {
    if (left.kind == "placemarker") {
        right.space = left.space;
        return {right};
    }
    if (right.kind == "placemarker")
        return {left};
    std::string combined = left.spelling + right.spelling;
    std::optional<std::string> kind = single_token(combined);
    if (kind)
        return {{*kind, combined, 0, left.space, intersection(left.hide, right.hide)}};
    processor.diagnostic(inclusion.position(invocation.line), "error",
                         "pasting \"" + left.spelling + "\" and \"" + right.spelling +
                             "\" does not give a valid preprocessing token");
    right.space = false;
    return {left, right};
}
struct SubstitutionItem {
    bool paste = false;
    Tokens tokens;
    Token operator_token;
};
static Tokens substitute(Preprocessor &processor, const Inclusion &inclusion, const Macro &macro,
                         const Token &invocation, const std::vector<Tokens> &raw,
                         const std::set<std::string> &hide) {
    std::map<std::string, size_t> parameters;
    for (size_t i = 0; i < macro.parameters.size(); ++i)
        parameters[macro.parameters[i]] = i;
    std::vector<std::optional<Tokens>> expanded(raw.size());
    std::vector<SubstitutionItem> items;
    for (size_t i = 0; i < macro.replacement.size(); ++i) {
        Token token = macro.replacement[i];
        if (token.spelling == "#" && macro.function) {
            const Token &parameter = macro.replacement[++i];
            items.push_back({false, {stringize(raw[parameters.at(parameter.spelling)], token)}});
        } else if (token.spelling == "##")
            items.push_back({true, {}, token});
        else if (token.kind == "identifier" && parameters.count(token.spelling)) {
            size_t index = parameters.at(token.spelling);
            bool adjacent =
                (i > 0 && macro.replacement[i - 1].spelling == "##") ||
                (i + 1 < macro.replacement.size() && macro.replacement[i + 1].spelling == "##");
            Tokens sequence;
            if (adjacent)
                sequence = raw[index];
            else {
                if (!expanded[index])
                    expanded[index] = expand(processor, inclusion, raw[index]);
                sequence = *expanded[index];
            }
            if (sequence.empty())
                sequence.push_back({"placemarker", "", 0, token.space, {}});
            else
                sequence[0].space = token.space;
            items.push_back({false, std::move(sequence)});
        } else
            items.push_back({false, {token}});
    }
    Tokens combined;
    for (size_t i = 0; i < items.size(); ++i) {
        if (!items[i].paste)
            combined.insert(combined.end(), items[i].tokens.begin(), items[i].tokens.end());
        else {
            Token left = combined.back();
            combined.pop_back();
            SubstitutionItem &right = items[++i];
            Tokens sequence = right.paste ? Tokens{right.operator_token} : right.tokens;
            Tokens result = paste(processor, inclusion, left, sequence.front(), invocation);
            combined.insert(combined.end(), result.begin(), result.end());
            combined.insert(combined.end(), sequence.begin() + 1, sequence.end());
        }
    }
    Tokens result;
    bool space = false;
    for (Token token : combined) {
        if (token.kind == "placemarker") {
            if (token.space)
                space = true;
            continue;
        }
        if (space) {
            token.space = true;
            space = false;
        }
        token.line = invocation.line;
        token.hide.insert(hide.begin(), hide.end());
        result.push_back(std::move(token));
    }
    if (!result.empty())
        result[0].space = invocation.space;
    return result;
}
Tokens expand(Preprocessor &processor, const Inclusion &inclusion, const Tokens &tokens) {
    std::deque<Token> input(tokens.begin(), tokens.end());
    Tokens result;
    while (!input.empty()) {
        Token invocation = input.front();
        input.pop_front();
        const std::string &name = invocation.spelling;
        if (invocation.kind != "identifier" || invocation.hide.count(name)) {
            result.push_back(invocation);
            continue;
        }
        if (builtin(name)) {
            ++processor.builtin_counts[name];
            Token token;
            token.line = invocation.line;
            token.space = invocation.space;
            token.kind = name == "__FILE__" ? "string" : "number";
            if (name == "__LINE__")
                token.spelling = std::to_string(inclusion.position(invocation.line).line);
            else if (name == "__FILE__")
                token.spelling = "\"" + inclusion.display_file + "\"";
            else
                token.spelling = std::to_string(processor.counter++);
            result.push_back(std::move(token));
            continue;
        }
        auto found = processor.macros.find(name);
        if (found == processor.macros.end()) {
            result.push_back(invocation);
            continue;
        }
        const std::shared_ptr<Macro> macro = found->second;
        std::set<std::string> hide = invocation.hide;
        std::vector<Tokens> raw;
        if (macro->function) {
            if (input.empty() || input.front().spelling != "(") {
                result.push_back(invocation);
                continue;
            }
            std::vector<Tokens> arguments(1);
            std::vector<Token> commas;
            int depth = 0;
            size_t close = 1;
            for (; close < input.size(); ++close) {
                const Token &token = input[close];
                if (token.spelling == ")" && depth == 0)
                    break;
                if (token.spelling == "," && depth == 0) {
                    commas.push_back(token);
                    arguments.emplace_back();
                } else {
                    if (token.spelling == "(")
                        ++depth;
                    else if (token.spelling == ")")
                        --depth;
                    arguments.back().push_back(token);
                }
            }
            std::string error;
            size_t k = arguments.size(), n = macro->parameters.size() - (macro->variadic ? 1 : 0);
            if (close == input.size())
                error = "unterminated argument list invoking macro \"" + name + "\"";
            else if (!macro->variadic && n == 0 && !(k == 1 && arguments[0].empty()))
                error = "macro \"" + name + "\" passed " + std::to_string(k) +
                        " arguments, but takes just 0";
            else if (k < n)
                error = "macro \"" + name + "\" requires " + std::to_string(n) +
                        " arguments, but only " + std::to_string(k) + " given";
            else if (k > n && !macro->variadic)
                error = "macro \"" + name + "\" passed " + std::to_string(k) +
                        " arguments, but takes just " + std::to_string(n);
            if (!error.empty()) {
                processor.diagnostic(inclusion.position(invocation.line), "error", error);
                result.push_back(invocation);
                continue;
            }
            hide = intersection(invocation.hide, input[close].hide);
            raw.assign(arguments.begin(), arguments.begin() + n);
            if (macro->variadic) {
                Tokens variadic;
                for (size_t i = n; i < arguments.size(); ++i) {
                    if (i > n)
                        variadic.push_back(commas[i - 1]);
                    variadic.insert(variadic.end(), arguments[i].begin(), arguments[i].end());
                }
                raw.push_back(std::move(variadic));
            }
            input.erase(input.begin(), input.begin() + close + 1);
        }
        hide.insert(name);
        Tokens replacement = substitute(processor, inclusion, *macro, invocation, raw, hide);
        ++macro->expanded;
        if (replacement.empty() && invocation.space && !input.empty())
            input.front().space = true;
        for (auto it = replacement.rbegin(); it != replacement.rend(); ++it)
            input.push_front(*it);
    }
    return result;
}

#include "preprocessor.hpp"
static int digit_value(char c) {
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'a' && c <= 'f')
        return c - 'a' + 10;
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return -1;
}
static int64_t integer_constant(const std::string &spelling) {
    std::string text = spelling;
    for (const std::string &suffix :
         {std::string("ll"), std::string("LL"), std::string("l"), std::string("L")})
        if (text.size() > suffix.size() &&
            text.compare(text.size() - suffix.size(), suffix.size(), suffix) == 0) {
            text.resize(text.size() - suffix.size());
            break;
        }
    int base = 10;
    size_t first = 0;
    bool valid = !text.empty();
    if (text.size() >= 2 && text[0] == '0' && (text[1] == 'x' || text[1] == 'X')) {
        base = 16;
        first = 2;
        if (first == text.size())
            valid = false;
    } else if (!text.empty() && text[0] == '0')
        base = 8;
    else if (text.empty() || text[0] < '1' || text[0] > '9')
        valid = false;
    for (size_t i = first; i < text.size(); ++i) {
        int digit = digit_value(text[i]);
        if (digit < 0 || digit >= base)
            valid = false;
    }
    if (!valid)
        throw PreprocessingError{"invalid integer constant \"" + spelling + "\""};
    int64_t value = 0;
    for (size_t i = first; i < text.size(); ++i)
        value = value * base + digit_value(text[i]);
    return value;
}
static int64_t character_constant(const std::string &spelling) {
    std::string body = spelling.substr(1, spelling.size() - 2);
    if (body.size() == 1 && body[0] != '\'' && body[0] != '\\')
        return static_cast<unsigned char>(body[0]);
    if (body.size() == 2 && body[0] == '\\') {
        const std::map<char, int> escapes = {{'n', 10},  {'t', 9},  {'\\', 92},
                                             {'\'', 39}, {'"', 34}, {'0', 0}};
        auto found = escapes.find(body[1]);
        if (found != escapes.end())
            return found->second;
    }
    throw PreprocessingError{"invalid character constant " + spelling};
}
static int precedence(const std::string &op) {
    if (op == "||")
        return 1;
    if (op == "&&")
        return 2;
    if (op == "|")
        return 3;
    if (op == "^")
        return 4;
    if (op == "&")
        return 5;
    if (op == "==" || op == "!=")
        return 6;
    if (word_in("< > <= >=", op))
        return 7;
    if (op == "<<" || op == ">>")
        return 8;
    if (op == "+" || op == "-")
        return 9;
    if (word_in("* / %", op))
        return 10;
    return 0;
}
static std::unique_ptr<ConditionExpr> node(const std::string &kind) {
    auto result = std::make_unique<ConditionExpr>();
    result->kind = kind;
    return result;
}
struct ExpressionParser {
    const Tokens &tokens;
    size_t index = 0;
    std::string peek() const { return index == tokens.size() ? "" : tokens[index].spelling; }
    std::unique_ptr<ConditionExpr> expression() {
        auto first = binary(1);
        if (peek() == "?") {
            ++index;
            auto second = expression();
            if (peek() != ":")
                throw PreprocessingError{"'?' without following ':'"};
            ++index;
            auto third = expression();
            auto result = node("conditional");
            result->children.push_back(std::move(first));
            result->children.push_back(std::move(second));
            result->children.push_back(std::move(third));
            return result;
        }
        return first;
    }
    std::unique_ptr<ConditionExpr> binary(int minimum) {
        auto left = unary();
        while (true) {
            int level = precedence(peek());
            if (!level || level < minimum)
                break;
            std::string op = peek();
            ++index;
            auto right = binary(level + 1);
            auto result = node("binary");
            result->op = op;
            result->children.push_back(std::move(left));
            result->children.push_back(std::move(right));
            left = std::move(result);
        }
        return left;
    }
    std::unique_ptr<ConditionExpr> unary() {
        if (word_in("+ - ! ~", peek())) {
            std::string op = peek();
            ++index;
            auto result = node("unary");
            result->op = op;
            result->children.push_back(unary());
            return result;
        }
        return primary();
    }
    std::unique_ptr<ConditionExpr> primary() {
        if (index == tokens.size())
            throw PreprocessingError{"expected value at end of expression"};
        const Token &token = tokens[index++];
        if (token.kind == "number" || token.kind == "character") {
            auto result = node("constant");
            result->value = token.kind == "number" ? integer_constant(token.spelling)
                                                   : character_constant(token.spelling);
            return result;
        }
        if (token.kind == "identifier") {
            auto result = node("identifier");
            result->name = token.spelling;
            return result;
        }
        if (token.spelling == "(") {
            auto result = expression();
            if (peek() != ")")
                throw PreprocessingError{"missing ')' in expression"};
            ++index;
            return result;
        }
        throw PreprocessingError{"expected value before \"" + token.spelling + "\""};
    }
};
std::unique_ptr<ConditionExpr> parse_condition(const Tokens &tokens, const std::string &directive) {
    if (tokens.empty())
        throw PreprocessingError{"#" + directive + " with no expression"};
    ExpressionParser parser{tokens};
    auto result = parser.expression();
    if (parser.index < tokens.size())
        throw PreprocessingError{"missing binary operator before \"" + parser.peek() + "\""};
    return result;
}
int64_t evaluate_condition(const ConditionExpr &e,
                           const std::function<void(const std::string &)> &warning) {
    if (e.kind == "constant")
        return e.value;
    if (e.kind == "identifier") {
        warning("identifier \"" + e.name + "\" evaluates to 0");
        return 0;
    }
    int64_t a = evaluate_condition(*e.children[0], warning);
    if (e.kind == "unary") {
        if (e.op == "+")
            return a;
        if (e.op == "-")
            return -a;
        if (e.op == "!")
            return a == 0;
        return -a - 1;
    }
    if (e.kind == "conditional")
        return evaluate_condition(*e.children[a ? 1 : 2], warning);
    if (e.op == "&&" && !a)
        return 0;
    if (e.op == "||" && a)
        return 1;
    int64_t b = evaluate_condition(*e.children[1], warning);
    if (e.op == "+")
        return a + b;
    if (e.op == "-")
        return a - b;
    if (e.op == "*")
        return a * b;
    if (e.op == "/" || e.op == "%") {
        if (!b)
            throw PreprocessingError{"division by zero in #if"};
        int64_t q = a / b;
        return e.op == "/" ? q : a - b * q;
    }
    if (e.op == "<<")
        return a * (int64_t(1) << b);
    if (e.op == ">>") {
        int64_t divisor = int64_t(1) << b, q = a / divisor;
        if (a < 0 && a % divisor)
            --q;
        return q;
    }
    if (e.op == "&" || e.op == "|" || e.op == "^") {
        uint32_t left = static_cast<uint32_t>(a), right = static_cast<uint32_t>(b);
        uint32_t value = e.op == "&" ? left & right : e.op == "|" ? left | right : left ^ right;
        return value >= 0x80000000u ? static_cast<int64_t>(value) - 4294967296LL : value;
    }
    if (e.op == "==")
        return a == b;
    if (e.op == "!=")
        return a != b;
    if (e.op == "<")
        return a < b;
    if (e.op == ">")
        return a > b;
    if (e.op == "<=")
        return a <= b;
    if (e.op == ">=")
        return a >= b;
    return b != 0;
}

#include "preprocessor.hpp"
std::string directive_name(const Tokens &tokens) {
    return tokens.size() >= 2 && tokens[0].spelling == "#" && tokens[1].kind == "identifier"
               ? tokens[1].spelling
               : "";
}
static std::string detect_guard(const std::vector<LogicalLine> &logical) {
    std::vector<const Tokens *> lines;
    for (const LogicalLine &line : logical)
        if (!line.tokens.empty())
            lines.push_back(&line.tokens);
    if (lines.empty())
        return "";
    const Tokens &first = *lines.front();
    const Tokens &last = *lines.back();
    if (first.size() != 3 || first[0].spelling != "#" || first[1].spelling != "ifndef" ||
        first[1].kind != "identifier" || first[2].kind != "identifier" || last.size() != 2 ||
        last[0].spelling != "#" || last[1].spelling != "endif" || last[1].kind != "identifier")
        return "";
    int depth = 0;
    for (size_t i = 0; i < lines.size(); ++i) {
        std::string name = directive_name(*lines[i]);
        if (word_in("elif elifdef elifndef else", name) && depth == 1)
            return "";
        if (word_in("if ifdef ifndef", name))
            ++depth;
        else if (name == "endif")
            --depth;
        if (depth == 0 && i + 1 < lines.size())
            return "";
    }
    return depth == 0 ? first[2].spelling : "";
}
std::string IncludeManager::search(const std::string &name, bool quoted) const {
    std::vector<std::string> paths;
    if (quoted)
        paths.push_back(name);
    paths.push_back("include/" + name);
    for (const std::string &path : paths)
        if (std::filesystem::is_regular_file("input/" + path))
            return path;
    return "";
}
FileData *IncludeManager::load(const std::string &path) {
    auto found = files.find(path);
    if (found != files.end())
        return found->second.get();
    std::ifstream input("input/" + path);
    std::string source((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
    auto file = std::make_unique<FileData>();
    file->path = path;
    file->lines = lex_source(source);
    file->physical_lines = static_cast<int>(std::count(source.begin(), source.end(), '\n'));
    file->guard = detect_guard(file->lines);
    FileData *result = file.get();
    files[path] = std::move(file);
    order.push_back(path);
    return result;
}

#include "preprocessor.hpp"
bool word_in(const std::string &words, const std::string &word) {
    std::istringstream input(words);
    std::string current;
    while (input >> current)
        if (current == word)
            return true;
    return false;
}
static bool identifier_start(char c) {
    return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}
static bool digit(char c) { return c >= '0' && c <= '9'; }
ReadToken read_token(const std::string &source, size_t index, bool header) {
    char c = source[index];
    size_t n = source.size();
    if (header && c == '<') {
        size_t end = source.find('>', index + 1), newline = source.find('\n', index + 1);
        if (end != std::string::npos && (newline == std::string::npos || end < newline))
            return {"header", source.substr(index, end + 1 - index), end + 1};
    }
    if (identifier_start(c)) {
        size_t end = index + 1;
        while (end < n && (identifier_start(source[end]) || digit(source[end])))
            ++end;
        return {"identifier", source.substr(index, end - index), end};
    }
    if (digit(c) || (c == '.' && index + 1 < n && digit(source[index + 1]))) {
        size_t end = index + 1;
        while (end < n) {
            if (std::string("eEpP").find(source[end]) != std::string::npos && end + 1 < n &&
                (source[end + 1] == '+' || source[end + 1] == '-'))
                end += 2;
            else if (identifier_start(source[end]) || digit(source[end]) || source[end] == '.')
                ++end;
            else
                break;
        }
        return {"number", source.substr(index, end - index), end};
    }
    if (c == '\'' || c == '"') {
        size_t end = index + 1;
        while (end < n && source[end] != '\n') {
            if (source[end] == c)
                return {c == '\'' ? "character" : "string", source.substr(index, end + 1 - index),
                        end + 1};
            if (source[end] == '\\' && end + 1 < n && source[end + 1] != '\n')
                end += 2;
            else
                ++end;
        }
    }
    static const std::vector<std::string> punctuators = {
        "...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=",
        "&&",  "||",  "*=",  "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##", "[",
        "]",   "(",   ")",   "{",  "}",  ".",  "&",  "*",  "+",  "-",  "~",  "!",
        "/",   "%",   "<",   ">",  "^",  "|",  "?",  ":",  ";",  "=",  ",",  "#"};
    for (const std::string &punctuator : punctuators)
        if (source.compare(index, punctuator.size(), punctuator) == 0)
            return {"punctuator", punctuator, index + punctuator.size()};
    return {"other", source.substr(index, 1), index + 1};
}
static std::vector<LogicalLine> scan(const std::string &source, const std::vector<int> &positions,
                                     int start) {
    std::vector<LogicalLine> lines;
    Tokens tokens;
    bool spaced = true;
    size_t index = 0;
    while (index < source.size()) {
        if (source[index] == ' ') {
            spaced = true;
            ++index;
        } else if (source[index] == '\n') {
            int end = positions[index++];
            lines.push_back({tokens, start, end});
            tokens.clear();
            start = end + 1;
            spaced = true;
        } else if (source.compare(index, 2, "/*") == 0) {
            size_t end = source.find("*/", index + 2);
            index = end == std::string::npos ? source.size() : end + 2;
            spaced = true;
        } else if (source.compare(index, 2, "//") == 0) {
            size_t end = source.find('\n', index);
            index = end == std::string::npos ? source.size() : end;
            spaced = true;
        } else {
            bool header =
                tokens.size() == 2 && tokens[0].spelling == "#" && tokens[1].spelling == "include";
            ReadToken token = read_token(source, index, header);
            tokens.push_back({token.kind, token.spelling, positions[index], spaced, {}});
            index = token.end;
            spaced = false;
        }
    }
    if (!tokens.empty())
        lines.push_back({tokens, start, positions.back()});
    return lines;
}
std::vector<LogicalLine> lex_source(const std::string &source) {
    std::string characters;
    std::vector<int> positions;
    int line = 1;
    for (size_t i = 0; i < source.size();) {
        if (i + 1 < source.size() && source[i] == '\\' && source[i + 1] == '\n') {
            i += 2;
            ++line;
            continue;
        }
        char c = source[i++];
        characters += c;
        positions.push_back(line);
        if (c == '\n')
            ++line;
    }
    return scan(characters, positions, 1);
}
Tokens lex_definition(const std::string &text, int line) {
    std::string source = text + "\n";
    std::vector<int> positions(source.size(), line);
    Tokens result;
    for (const LogicalLine &logical : scan(source, positions, line))
        result.insert(result.end(), logical.tokens.begin(), logical.tokens.end());
    return result;
}
std::string render(const Tokens &tokens) {
    std::string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i && tokens[i].space)
            result += " ";
        result += tokens[i].spelling;
    }
    return result;
}
std::optional<std::string> single_token(const std::string &source) {
    if (source.empty() || source.compare(0, 2, "//") == 0 || source.compare(0, 2, "/*") == 0)
        return std::nullopt;
    ReadToken token = read_token(source, 0);
    if (token.end != source.size())
        return std::nullopt;
    return token.kind;
}

#include "preprocessor.hpp"
std::optional<Header> read_header(const Tokens &tokens, size_t index) {
    if (index >= tokens.size())
        return std::nullopt;
    const Token &token = tokens[index];
    if (token.kind == "string" || token.kind == "header")
        return Header{token.spelling, token.spelling.substr(1, token.spelling.size() - 2),
                      token.spelling[0] == '"', index + 1};
    if (token.spelling == "<") {
        size_t end = index + 1;
        while (end < tokens.size() && tokens[end].spelling != ">")
            ++end;
        if (end == tokens.size())
            throw PreprocessingError{"missing terminating > character"};
        std::string name = render(Tokens(tokens.begin() + index + 1, tokens.begin() + end));
        return Header{"<" + name + ">", name, false, end + 1};
    }
    return std::nullopt;
}
static bool separator_needed(const std::string &left, const std::string &right) {
    if (left == "/" && (right[0] == '/' || right[0] == '*'))
        return true;
    return read_token(left + right, 0).end != left.size();
}
static std::string output_render(const Tokens &tokens) {
    std::string result;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i && (tokens[i].space || separator_needed(tokens[i - 1].spelling, tokens[i].spelling)))
            result += " ";
        result += tokens[i].spelling;
    }
    return result;
}
static bool decimal_token(const Token &token) {
    return token.kind == "number" && !token.spelling.empty() &&
           std::all_of(token.spelling.begin(), token.spelling.end(),
                       [](char c) { return c >= '0' && c <= '9'; });
}
void Preprocessor::diagnostic(Position position, const std::string &kind,
                              const std::string &message) {
    diagnostics.push_back(position_text(position) + ": " + kind + ": " + message);
    ++diagnostic_counts[kind];
}
void Preprocessor::event(Position position, const std::string &content) {
    history.push_back(position_text(position) + ": " + content);
}
void Preprocessor::poison_check(const Inclusion &inclusion, const Tokens &tokens) {
    for (const Token &token : tokens)
        if (token.kind == "identifier" && poisoned.count(token.spelling))
            diagnostic(inclusion.position(token.line), "error",
                       "attempt to use poisoned \"" + token.spelling + "\"");
}
void Preprocessor::unused_check(const Macro &macro) {
    if (macro.main_file && macro.expanded == 0 && macro.tested == 0)
        diagnostic(macro.position, "warning", "macro \"" + macro.name + "\" is not used");
}
void Preprocessor::define(Tokens tokens, Position position, bool main_file) {
    std::shared_ptr<Macro> macro;
    try {
        macro = parse_definition(std::move(tokens), position, main_file);
    } catch (const PreprocessingError &error) {
        diagnostic(position, "error", error.message);
        return;
    }
    std::string operation = "define";
    auto previous = macros.find(macro->name);
    if (previous == macros.end()) {
        macros[macro->name] = macro;
        ever_defined.insert(macro->name);
    } else if (previous->second->identical(*macro))
        operation = "identical";
    else {
        unused_check(*previous->second);
        diagnostic(position, "warning",
                   "\"" + macro->name + "\" redefined (previous definition at " +
                       position_text(previous->second->position) + ")");
        macros[macro->name] = macro;
        ever_defined.insert(macro->name);
        operation = "redefine";
    }
    event(position, operation + " " + macro->signature());
}
void Preprocessor::undefine(const Tokens &tokens, Position position) {
    try {
        check_name(tokens, "undef");
    } catch (const PreprocessingError &error) {
        diagnostic(position, "error", error.message);
        return;
    }
    if (tokens.size() > 1)
        diagnostic(position, "warning", "extra tokens at end of #undef directive");
    const std::string &name = tokens[0].spelling;
    auto previous = macros.find(name);
    if (previous != macros.end()) {
        unused_check(*previous->second);
        macros.erase(previous);
        event(position, "undef " + name);
    } else
        event(position, "undef " + name + " (not defined)");
}
void Preprocessor::process_defines() {
    std::ifstream input("input/defines.txt");
    std::string line;
    int number = 0;
    while (std::getline(input, line)) {
        ++number;
        if (line.empty())
            continue;
        size_t equal = line.find('=');
        std::string text = equal == std::string::npos
                               ? line + " 1"
                               : line.substr(0, equal) + " " + line.substr(equal + 1);
        define(lex_definition(text, number), {"defines.txt", number}, false);
    }
}
void Preprocessor::marker(const std::string &file, int line, int flag) {
    std::string text = "# " + std::to_string(line) + " \"" + file + "\"";
    if (flag)
        text += " " + std::to_string(flag);
    output.push_back(text);
    previous = {file, line - 1};
}
void Preprocessor::output_line(Inclusion &inclusion, int physical, const std::string &text) {
    Position position = inclusion.position(physical);
    if (position.file == previous.file && previous.line < position.line &&
        static_cast<int64_t>(position.line) <= static_cast<int64_t>(previous.line) + 8)
        for (int64_t i = static_cast<int64_t>(previous.line) + 1; i < position.line; ++i)
            output.emplace_back();
    else
        marker(position.file, position.line);
    output.push_back(text);
    previous = position;
    ++inclusion.source->output_lines;
}
void Preprocessor::flush(Inclusion &inclusion) {
    Tokens segment = std::move(inclusion.segment);
    inclusion.segment.clear();
    if (segment.empty())
        return;
    poison_check(inclusion, segment);
    Tokens expanded = expand(*this, inclusion, segment);
    for (size_t start = 0; start < expanded.size();) {
        size_t end = start + 1;
        while (end < expanded.size() && expanded[end].line == expanded[start].line)
            ++end;
        output_line(inclusion, expanded[start].line,
                    output_render(Tokens(expanded.begin() + start, expanded.begin() + end)));
        start = end;
    }
}
bool Preprocessor::macro_defined(const std::string &name) {
    auto found = macros.find(name);
    if (found != macros.end()) {
        ++found->second->tested;
        return true;
    }
    return builtin(name) || name == "__has_include";
}
Tokens Preprocessor::replace_operators(const Tokens &operands) {
    Tokens result;
    for (size_t position = 0; position < operands.size();) {
        Token token = operands[position];
        size_t index = position + 1;
        bool value = false;
        if (token.kind == "identifier" && token.spelling == "defined") {
            bool parenthesized = index < operands.size() && operands[index].spelling == "(";
            if (parenthesized)
                ++index;
            if (index == operands.size() || operands[index].kind != "identifier")
                throw PreprocessingError{"operator \"defined\" requires an identifier"};
            std::string name = operands[index++].spelling;
            if (parenthesized) {
                if (index == operands.size() || operands[index].spelling != ")")
                    throw PreprocessingError{"missing ')' after \"defined\""};
                ++index;
            }
            value = macro_defined(name);
        } else if (token.kind == "identifier" && token.spelling == "__has_include") {
            if (index == operands.size() || operands[index].spelling != "(")
                throw PreprocessingError{"missing '(' after \"__has_include\""};
            std::optional<Header> header = read_header(operands, index + 1);
            if (!header || header->name.empty())
                throw PreprocessingError{"operator \"__has_include\" requires a header-name"};
            index = header->next;
            if (index == operands.size() || operands[index].spelling != ")")
                throw PreprocessingError{"missing ')' after \"__has_include\" operand"};
            ++index;
            value = !manager.search(header->name, header->quoted).empty();
        } else {
            result.push_back(token);
            ++position;
            continue;
        }
        result.push_back({"number", value ? "1" : "0", token.line, token.space, {}});
        position = index;
    }
    return result;
}
TestResult Preprocessor::test(Inclusion &inclusion, const LogicalLine &line,
                              const std::string &name, const Tokens &operands) {
    Position position = inclusion.position(line.tokens[0].line);
    poison_check(inclusion, operands);
    TestResult result;
    if (name != "if" && name != "elif") {
        if (operands.empty()) {
            diagnostic(position, "error", "no macro name given in #" + name + " directive");
            return result;
        }
        if (operands[0].kind != "identifier") {
            diagnostic(position, "error", "macro names must be identifiers");
            return result;
        }
        if (operands.size() > 1)
            diagnostic(position, "warning", "extra tokens at end of #" + name + " directive");
        bool defined = macro_defined(operands[0].spelling);
        if (name == "ifndef" || name == "elifndef")
            defined = !defined;
        result.valid = true;
        result.value = defined;
        return result;
    }
    Tokens replaced;
    try {
        replaced = replace_operators(operands);
    } catch (const PreprocessingError &error) {
        diagnostic(position, "error", error.message);
        return result;
    }
    result.expanded = expand(*this, inclusion, replaced);
    result.was_expanded = true;
    try {
        std::unique_ptr<ConditionExpr> expression = parse_condition(result.expanded, name);
        result.value = evaluate_condition(*expression, [&](const std::string &message) {
            diagnostic(position, "warning", message);
        });
        result.valid = true;
    } catch (const PreprocessingError &error) {
        diagnostic(position, "error", error.message);
    }
    return result;
}
static std::string test_description(const std::string &name, const TestResult &test) {
    std::string description = "not taken (error)";
    if (test.valid) {
        description = test.value ? "taken" : "not taken";
        if (name == "if" || name == "elif")
            description += " (value " + std::to_string(test.value) + ")";
    }
    if (test.was_expanded)
        description += " [" + output_render(test.expanded) + "]";
    return description;
}
void Preprocessor::close_region(Inclusion &inclusion, ConditionalBlock &block, int end) {
    int start = block.skip_start;
    if (start && end >= start) {
        Position first = inclusion.position(start), last = inclusion.position(end);
        regions.push_back(first.file + ":" + std::to_string(first.line) + "-" +
                          std::to_string(last.line) + " lines=" + std::to_string(end - start + 1));
        inclusion.source->skipped_lines += end - start + 1;
    }
    block.skip_start = 0;
}
void Preprocessor::conditional_record(Position position, size_t depth, const std::string &name,
                                      const Tokens &operands, const std::string &description) {
    std::string directive = "#" + name;
    if (!operands.empty())
        directive += " " + render(operands);
    conditionals.push_back(position_text(position) + ": " + std::string(2 * depth, ' ') +
                           directive + " => " + description);
    const std::vector<std::pair<std::string, std::string>> prefixes = {
        {"taken", "taken"},
        {"not taken", "not_taken"},
        {"skipped", "skipped"},
        {"not evaluated", "not_evaluated"},
        {"closes", "endif"}};
    for (const auto &prefix : prefixes)
        if (description.compare(0, prefix.first.size(), prefix.first) == 0) {
            ++condition_counts[prefix.second];
            break;
        }
}
void Preprocessor::conditional(Inclusion &inclusion, const LogicalLine &line,
                               const std::string &name, const Tokens &operands) {
    Position position = inclusion.position(line.tokens[0].line);
    if (word_in("if ifdef ifndef", name)) {
        ConditionalBlock block;
        block.kind = name;
        block.start = position;
        block.parent = !inclusion.skipping();
        std::string description = "skipped";
        if (block.parent) {
            TestResult tested = test(inclusion, line, name, operands);
            if (tested.valid && tested.value)
                block.chosen = block.active = true;
            else
                block.skip_start = line.end + 1;
            description = test_description(name, tested);
        }
        conditional_record(position, inclusion.stack.size(), name, operands, description);
        inclusion.stack.push_back(block);
        return;
    }
    if (inclusion.stack.empty()) {
        diagnostic(position, "error", "#" + name + " without #if");
        return;
    }
    size_t depth = inclusion.stack.size() - 1;
    ConditionalBlock &block = inclusion.stack.back();
    close_region(inclusion, block, line.start - 1);
    std::string description;
    if (name == "endif") {
        if (block.parent && !operands.empty())
            diagnostic(position, "warning", "extra tokens at end of #endif directive");
        description = "closes #" + block.kind + " at line " + std::to_string(block.start.line);
        inclusion.stack.pop_back();
    } else {
        if (block.else_seen)
            diagnostic(position, "error", "#" + name + " after #else");
        if (name == "else") {
            if (block.parent && !operands.empty())
                diagnostic(position, "warning", "extra tokens at end of #else directive");
            block.else_seen = true;
            if (block.parent) {
                block.active = !block.chosen;
                block.chosen = true;
                description = block.active ? "taken" : "not taken";
            } else {
                block.active = false;
                description = "skipped";
            }
        } else if (!block.parent) {
            block.active = false;
            description = "skipped";
        } else if (block.chosen) {
            block.active = false;
            description = "not evaluated";
        } else {
            TestResult tested = test(inclusion, line, name, operands);
            block.active = tested.valid && tested.value;
            if (block.active)
                block.chosen = true;
            description = test_description(name, tested);
        }
        if (block.parent && !block.active)
            block.skip_start = line.end + 1;
    }
    conditional_record(position, depth, name, operands, description);
}
void Preprocessor::include(Inclusion &inclusion, const LogicalLine &line, Tokens operands) {
    Position position = inclusion.position(line.tokens[0].line);
    std::optional<Header> header;
    try {
        header = read_header(operands, 0);
        if (!header && !operands.empty()) {
            operands = expand(*this, inclusion, operands);
            header = read_header(operands, 0);
        }
    } catch (const PreprocessingError &error) {
        diagnostic(position, "error", error.message);
        return;
    }
    if (!header) {
        diagnostic(position, "error", "#include expects \"FILENAME\" or <FILENAME>");
        return;
    }
    if (header->next < operands.size())
        diagnostic(position, "warning", "extra tokens at end of #include directive");
    if (header->name.empty()) {
        diagnostic(position, "error", "empty filename in #include");
        return;
    }
    std::string prefix = std::string(2 * (inclusion.depth + 1), ' ') +
                         std::to_string(line.tokens[0].line) + ": ",
                path = manager.search(header->name, header->quoted);
    if (path.empty()) {
        tree.push_back(prefix + header->rendering + " [not found]");
        diagnostic(position, "error", "cannot find include file " + header->rendering);
        return;
    }
    auto previous = manager.files.find(path);
    if (previous != manager.files.end() && previous->second->once) {
        tree.push_back(prefix + path + " [skipped: pragma once]");
        ++previous->second->skipped;
        return;
    }
    if (previous != manager.files.end() && !previous->second->guard.empty() &&
        macros.count(previous->second->guard)) {
        tree.push_back(prefix + path + " [skipped: guard " + previous->second->guard + "]");
        ++previous->second->skipped;
        return;
    }
    if (inclusion.depth + 1 > 8) {
        tree.push_back(prefix + path + " [too deep]");
        diagnostic(position, "error", "#include nested too deeply");
        return;
    }
    tree.push_back(prefix + path);
    marker(path, 1, 1);
    process_file(path, inclusion.depth + 1);
    Position next = inclusion.position(line.end + 1);
    marker(next.file, next.line, 2);
}
void Preprocessor::line_directive(Inclusion &inclusion, const LogicalLine &line, Tokens operands) {
    Position position = inclusion.position(line.tokens[0].line);
    if (operands.empty() || !decimal_token(operands[0]))
        operands = expand(*this, inclusion, operands);
    if (operands.empty() || operands.size() > 2 || !decimal_token(operands[0]) ||
        (operands.size() == 2 && operands[1].kind != "string")) {
        diagnostic(position, "error", "invalid #line directive");
        return;
    }
    int64_t number = std::stoll(operands[0].spelling);
    if (number < 1 || number > 2147483647LL) {
        diagnostic(position, "error", "line number out of range");
        return;
    }
    inclusion.offset = static_cast<int>(number) - (line.end + 1);
    if (operands.size() == 2)
        inclusion.display_file = operands[1].spelling.substr(1, operands[1].spelling.size() - 2);
}
void Preprocessor::macro_pragma(Position position, const Tokens &operands,
                                const std::string &operation) {
    if (operands.size() != 4 || operands[1].spelling != "(" || operands[2].kind != "string" ||
        operands[3].spelling != ")") {
        diagnostic(position, "error", "invalid #pragma " + operation + " directive");
        return;
    }
    std::string name = operands[2].spelling.substr(1, operands[2].spelling.size() - 2);
    if (operation == "push_macro") {
        auto found = macros.find(name);
        saved[name].push_back(found == macros.end() ? nullptr : found->second);
        event(position, "push " + name);
        return;
    }
    auto &stack = saved[name];
    if (stack.empty()) {
        diagnostic(position, "warning", "no matching push_macro for \"" + name + "\"");
        return;
    }
    std::shared_ptr<Macro> macro = stack.back();
    stack.pop_back();
    if (!macro) {
        macros.erase(name);
        event(position, "pop " + name + " (undefined)");
    } else {
        macros[name] = macro;
        event(position, "pop " + name);
    }
}
void Preprocessor::pragma(Inclusion &inclusion, const LogicalLine &line, const Tokens &operands) {
    Position position = inclusion.position(line.tokens[0].line);
    std::string name =
        !operands.empty() && operands[0].kind == "identifier" ? operands[0].spelling : "";
    if (name == "once") {
        if (operands.size() > 1)
            diagnostic(position, "warning", "extra tokens at end of #pragma once directive");
        if (inclusion.depth == 0)
            diagnostic(position, "warning", "#pragma once in main file");
        inclusion.source->once = true;
    } else if (operands.size() >= 2 && operands[0].spelling == "GCC" &&
               operands[1].spelling == "poison") {
        for (size_t i = 2; i < operands.size(); ++i)
            if (operands[i].kind != "identifier") {
                diagnostic(position, "error", "invalid #pragma GCC poison directive");
                return;
            }
        for (size_t i = 2; i < operands.size(); ++i) {
            const std::string &name = operands[i].spelling;
            if (macros.count(name))
                diagnostic(position, "warning", "poisoning existing macro \"" + name + "\"");
            poisoned.insert(name);
        }
    } else if (name == "push_macro" || name == "pop_macro")
        macro_pragma(position, operands, name);
    else
        output_line(inclusion, line.tokens[0].line,
                    operands.empty() ? "#pragma" : "#pragma " + render(operands));
}
void Preprocessor::directive(Inclusion &inclusion, const LogicalLine &line, const std::string &name,
                             const Tokens &operands) {
    if (line.tokens.size() == 1)
        return;
    bool poisoning = name == "pragma" && operands.size() >= 2 && operands[0].spelling == "GCC" &&
                     operands[1].spelling == "poison";
    if (!poisoning)
        poison_check(inclusion, operands);
    Position position = inclusion.position(line.tokens[0].line);
    if (name == "define")
        define(operands, position, inclusion.depth == 0);
    else if (name == "undef")
        undefine(operands, position);
    else if (name == "include")
        include(inclusion, line, operands);
    else if (name == "line")
        line_directive(inclusion, line, operands);
    else if (name == "error" || name == "warning")
        diagnostic(position, name, "#" + name + (operands.empty() ? "" : " " + render(operands)));
    else if (name == "pragma")
        pragma(inclusion, line, operands);
    else
        diagnostic(position, "error",
                   "invalid preprocessing directive #" + line.tokens[1].spelling);
}
void Preprocessor::process_file(const std::string &path, int depth) {
    FileData *source = manager.load(path);
    ++source->entered;
    Inclusion inclusion;
    inclusion.source = source;
    inclusion.depth = depth;
    inclusion.display_file = path;
    for (const LogicalLine &line : source->lines) {
        bool is_directive = !line.tokens.empty() && line.tokens[0].spelling == "#";
        std::string name = directive_name(line.tokens);
        Tokens operands =
            line.tokens.size() > 2 ? Tokens(line.tokens.begin() + 2, line.tokens.end()) : Tokens{};
        if (is_directive && word_in("if ifdef ifndef elif elifdef elifndef else endif", name)) {
            flush(inclusion);
            conditional(inclusion, line, name, operands);
        } else if (inclusion.skipping())
            continue;
        else if (is_directive) {
            flush(inclusion);
            directive(inclusion, line, name, operands);
        } else
            inclusion.segment.insert(inclusion.segment.end(), line.tokens.begin(),
                                     line.tokens.end());
    }
    flush(inclusion);
    for (ConditionalBlock &block : inclusion.stack)
        close_region(inclusion, block, source->physical_lines);
    for (const ConditionalBlock &block : inclusion.stack)
        diagnostic(block.start, "error", "unterminated #" + block.kind);
}
static void write_lines(const std::string &name, const std::vector<std::string> &lines) {
    std::ofstream output("output/" + name);
    for (const std::string &line : lines) {
        size_t end = line.find_last_not_of(' ');
        output << (end == std::string::npos ? "" : line.substr(0, end + 1)) << "\n";
    }
}
void Preprocessor::write_reports() {
    std::vector<std::string> includes = tree;
    includes.push_back("");
    includes.push_back("== files ==");
    for (const auto &entry : manager.files) {
        const FileData &file = *entry.second;
        includes.push_back(entry.first + " entered=" + std::to_string(file.entered) +
                           " skipped=" + std::to_string(file.skipped) +
                           " lines=" + std::to_string(file.physical_lines) +
                           " output_lines=" + std::to_string(file.output_lines) +
                           " skipped_lines=" + std::to_string(file.skipped_lines) +
                           " guard=" + (file.guard.empty() ? "-" : file.guard) +
                           " once=" + (file.once ? "yes" : "no"));
    }
    includes.emplace_back();
    std::string current = "main.o:";
    bool has_path = false;
    for (const std::string &path : manager.order) {
        if (current.size() + 1 + path.size() > 76 && has_path) {
            includes.push_back(current + " \\");
            current = " ";
            has_path = false;
        }
        current += " " + path;
        has_path = true;
    }
    includes.push_back(current);
    std::vector<std::string> macro_report = {"== history =="};
    macro_report.insert(macro_report.end(), history.begin(), history.end());
    macro_report.emplace_back();
    macro_report.push_back("== table ==");
    std::map<std::string, std::set<std::string>> references;
    for (const auto &entry : macros) {
        const Macro &macro = *entry.second;
        std::set<std::string> parameters(macro.parameters.begin(), macro.parameters.end());
        for (const Token &token : macro.replacement)
            if (token.kind == "identifier" && macros.count(token.spelling) &&
                !parameters.count(token.spelling))
                references[entry.first].insert(token.spelling);
    }
    auto recursive = [&](const std::string &name) {
        std::vector<std::string> pending(references[name].begin(), references[name].end());
        std::set<std::string> seen;
        while (!pending.empty()) {
            std::string current = pending.back();
            pending.pop_back();
            if (current == name)
                return true;
            if (seen.insert(current).second)
                pending.insert(pending.end(), references[current].begin(),
                               references[current].end());
        }
        return false;
    };
    int objects = 0;
    for (const auto &entry : macros) {
        const Macro &macro = *entry.second;
        macro_report.push_back("#define " + macro.signature() +
                               (macro.replacement.empty() ? "" : " " + render(macro.replacement)));
        macro_report.push_back("  at " + position_text(macro.position) +
                               " expanded=" + std::to_string(macro.expanded) +
                               " tested=" + std::to_string(macro.tested) +
                               " recursive=" + (recursive(entry.first) ? "yes" : "no"));
        std::string refs = "  refs:";
        for (const std::string &name : references[entry.first])
            refs += " " + name;
        macro_report.push_back(refs);
        if (!macro.function)
            ++objects;
    }
    macro_report.emplace_back();
    macro_report.push_back("macros=" + std::to_string(macros.size()) +
                           " object_like=" + std::to_string(objects) +
                           " function_like=" + std::to_string(macros.size() - objects));
    std::string undefined = "undefined:";
    for (const std::string &name : ever_defined)
        if (!macros.count(name))
            undefined += " " + name;
    macro_report.push_back(undefined);
    macro_report.push_back(
        "builtins: __COUNTER__=" + std::to_string(builtin_counts["__COUNTER__"]) +
        " __FILE__=" + std::to_string(builtin_counts["__FILE__"]) +
        " __LINE__=" + std::to_string(builtin_counts["__LINE__"]));
    std::vector<std::string> conditional_report = conditionals;
    conditional_report.emplace_back();
    conditional_report.push_back("== skipped regions ==");
    conditional_report.insert(conditional_report.end(), regions.begin(), regions.end());
    conditional_report.emplace_back();
    conditional_report.push_back(
        "directives=" + std::to_string(conditionals.size()) +
        " taken=" + std::to_string(condition_counts["taken"]) +
        " not_taken=" + std::to_string(condition_counts["not_taken"]) +
        " skipped=" + std::to_string(condition_counts["skipped"]) +
        " not_evaluated=" + std::to_string(condition_counts["not_evaluated"]) + " endif=" +
        std::to_string(condition_counts["endif"]) + " regions=" + std::to_string(regions.size()));
    diagnostics.push_back("errors=" + std::to_string(diagnostic_counts["error"]) +
                          " warnings=" + std::to_string(diagnostic_counts["warning"]));
    std::filesystem::create_directories("output");
    write_lines("preprocessed.txt", output);
    write_lines("includes.txt", includes);
    write_lines("macros.txt", macro_report);
    write_lines("conditionals.txt", conditional_report);
    write_lines("diagnostics.txt", diagnostics);
}
int main() {
    Preprocessor preprocessor;
    preprocessor.process_defines();
    preprocessor.marker("main.c", 1);
    preprocessor.process_file("main.c", 0);
    for (const auto &entry : preprocessor.macros)
        preprocessor.unused_check(*entry.second);
    preprocessor.write_reports();
}

